"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import { Dialog, DialogClose, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog"
import { Field, FieldError, FieldLabel } from "@/components/ui/field"
import { Icon } from "@/components/ui/icon"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { CATEGORIES, type Category, type Transaction } from "@/components/blocks/dashboard-finance/components/dashboard-finance-data"

type Errors = { description?: string; amount?: string }

export function parseAmount(text: string): number | null {
  const t = text.replace(/[$\s]/g, "")
  if (!/^[\d.,]+$/.test(t)) return null
  const n = Number(t.includes(".") ? t.replace(/,/g, "") : t.replace(",", "."))
  return t !== "" && Number.isFinite(n) && n > 0 ? Math.round(n * 100) : null
}

export function AddTransaction({ date, onAdd }: { date: string; onAdd: (t: Omit<Transaction, "id">) => void }) {
  const uid = React.useId()
  const id = (name: string) => `${uid}-${name}`
  const [open, setOpen] = React.useState(false)
  const [description, setDescription] = React.useState("")
  const [amount, setAmount] = React.useState("")
  const [kind, setKind] = React.useState<"out" | "in">("out")
  const [category, setCategory] = React.useState<Category>("Groceries")
  const [errors, setErrors] = React.useState<Errors>({})

  const reset = () => {
    setDescription("")
    setAmount("")
    setKind("out")
    setCategory("Groceries")
    setErrors({})
  }

  function submit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault()
    const cents = parseAmount(amount)
    const next: Errors = {}
    if (!description.trim()) next.description = "Give it a name so you can find it later."
    if (cents === null) next.amount = "Write an amount above zero, like 12.50."
    setErrors(next)
    if (next.description || cents === null) {
      document.getElementById(id(next.description ? "description" : "amount"))?.focus()
      return
    }
    onAdd({ date, description: description.trim(), account: "Checking", category: kind === "in" ? "Income" : category, cents: kind === "in" ? cents : -cents, status: "pending" })
    setOpen(false)
  }

  return (
    <Dialog
      open={open}
      onOpenChange={(next) => {
        if (next) reset()
        setOpen(next)
      }}
    >
      <DialogTrigger asChild>
        <Button>
          <Icon name="plus" />
          Add transaction
        </Button>
      </DialogTrigger>
      <DialogContent tape="both" tapeKind="washi-dots">
        <DialogHeader>
          <DialogTitle>Add a transaction</DialogTitle>
          <DialogDescription>It goes in as pending until the bank agrees.</DialogDescription>
        </DialogHeader>
        <form id={id("form")} onSubmit={submit} noValidate className="flex flex-col gap-4">
          <Field data-invalid={errors.description ? "true" : undefined}>
            <FieldLabel htmlFor={id("description")}>What was it?</FieldLabel>
            <Input
              id={id("description")}
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              aria-invalid={errors.description ? true : undefined}
              aria-describedby={errors.description ? id("description-error") : undefined}
              placeholder="Ramen night"
            />
            <FieldError id={id("description-error")}>{errors.description}</FieldError>
          </Field>
          <Field data-invalid={errors.amount ? "true" : undefined}>
            <FieldLabel htmlFor={id("amount")}>How much?</FieldLabel>
            <Input
              id={id("amount")}
              inputMode="decimal"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
              aria-invalid={errors.amount ? true : undefined}
              aria-describedby={errors.amount ? id("amount-error") : undefined}
              placeholder="12.50"
            />
            <FieldError id={id("amount-error")}>{errors.amount}</FieldError>
          </Field>
          <RadioGroup value={kind} onValueChange={(v) => setKind(v as "out" | "in")} orientation="horizontal" aria-label="Money in or out">
            <div className="flex items-center gap-2">
              <RadioGroupItem id={id("out")} value="out" />
              <Label htmlFor={id("out")}>Money out</Label>
            </div>
            <div className="flex items-center gap-2">
              <RadioGroupItem id={id("in")} value="in" />
              <Label htmlFor={id("in")}>Money in</Label>
            </div>
          </RadioGroup>
          {kind === "out" ? (
            <Field>
              <FieldLabel htmlFor={id("category")}>Which pot?</FieldLabel>
              <Select value={category} onValueChange={(v) => setCategory(v as Category)}>
                <SelectTrigger id={id("category")} className="w-full">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {CATEGORIES.filter((c) => c !== "Income").map((c) => (
                    <SelectItem key={c} value={c}>
                      {c}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </Field>
          ) : null}
        </form>
        <DialogFooter>
          <DialogClose asChild>
            <Button variant="outline">Cancel</Button>
          </DialogClose>
          <Button type="submit" form={id("form")}>
            Add it
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

import { Receipt, ReceiptBarcode, ReceiptFooter, ReceiptHeader, ReceiptLine, ReceiptLines, ReceiptTotal } from "@/components/ui/receipt"
import { ACCOUNTS, money, shortDate, TODAY } from "@/components/blocks/dashboard-finance/components/dashboard-finance-data"

export function Balances() {
  const total = ACCOUNTS.reduce((sum, a) => sum + a.cents, 0)
  return (
    <section aria-labelledby="finance-balances" className="flex justify-center">
      <Receipt fastener="clip" seed="finance-balances">
        <ReceiptHeader>
          <h2 id="finance-balances">Balances</h2>
          <div>Marigold household</div>
          <div>{shortDate(TODAY)}, 2026</div>
        </ReceiptHeader>
        <ReceiptLines>
          {ACCOUNTS.map((a) => (
            <ReceiptLine key={a.name} price={a.cents < 0 ? <span className="text-red">{money(a.cents)}</span> : money(a.cents)}>
              {a.name}
            </ReceiptLine>
          ))}
        </ReceiptLines>
        <ReceiptTotal label="NET WORTH" circled seed="finance-total">
          {money(total)}
        </ReceiptTotal>
        <ReceiptBarcode value="0042 1187 0925" />
        <ReceiptFooter>Checked this morning. Thank you, come again.</ReceiptFooter>
      </Receipt>
    </section>
  )
}

import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Icon } from "@/components/ui/icon"
import { Progress } from "@/components/ui/progress"
import { StickyNote, StickyNoteContent, StickyNoteTitle } from "@/components/ui/sticky-note"
import { cn } from "@/lib/utils"
import { BUDGETS, CATEGORY_ICON, money } from "@/components/blocks/dashboard-finance/components/dashboard-finance-data"

type Tone = "green" | "hi" | "marker"

function toneOf(spent: number, budget: number): Tone {
  if (spent > budget) return "marker"
  return spent / budget >= 0.85 ? "hi" : "green"
}

export function Budgets({ spent, monthName, className }: { spent: Record<string, number>; monthName: string; className?: string }) {
  return (
    <Card className={cn("min-w-0", className)} seed="finance-budgets">
      <CardHeader>
        <CardTitle role="heading" aria-level={2}>
          Budgets
        </CardTitle>
        <CardDescription>What each pot has left in {monthName}</CardDescription>
      </CardHeader>
      <CardContent>
        <ul role="list" className="flex flex-col gap-5">
          {BUDGETS.map((b, i) => {
            const used = spent[b.category] ?? 0
            const left = b.cents - used
            const over = left < 0
            return (
              <li key={b.category} className="flex flex-col gap-1.5">
                <div className="flex items-baseline justify-between gap-3">
                  <span className="flex items-center gap-2 font-bold">
                    <Icon name={CATEGORY_ICON[b.category]} />
                    {b.category}
                  </span>
                  <span className="ll-num text-sm text-muted-foreground">
                    {money(used)} of {money(b.cents)}
                  </span>
                </div>
                <Progress
                  value={Math.min(100, (used / b.cents) * 100)}
                  tone={toneOf(used, b.cents)}
                  seed={`finance-budget-${i}`}
                  aria-label={`${b.category}: ${money(used)} spent of ${money(b.cents)}`}
                />
                {over ? (
                  <p className="flex items-center gap-1.5 text-sm font-bold text-red">
                    <Icon name="triangle-alert" size={14} />
                    Over by {money(-left)}
                  </p>
                ) : (
                  <p className="text-sm text-muted-foreground">{left === 0 ? "All of it spent, exactly" : `${money(left)} left`}</p>
                )}
              </li>
            )
          })}
        </ul>
      </CardContent>
    </Card>
  )
}

export function HeadsUp({ spent, className }: { spent: Record<string, number>; className?: string }) {
  const lines = BUDGETS.flatMap((b) => {
    const used = spent[b.category] ?? 0
    if (used > b.cents) return [`${b.category} is ${money(used - b.cents)} over.`]
    if (used === b.cents) return [`${b.category} is all spent.`]
    if (used / b.cents >= 0.85) return [`${b.category}: ${money(b.cents - used)} to go.`]
    return []
  })
  return (
    <StickyNote role="group" aria-label="Heads up" fastener="pin" seed="finance-headsup" className={cn("min-h-0 w-64 max-w-full self-center", className)}>
      <StickyNoteTitle>Heads up</StickyNoteTitle>
      <StickyNoteContent>
        {lines.length ? (
          <ul role="list" className="text-[1.15rem] leading-tight">
            {lines.map((l) => (
              <li key={l}>{l}</li>
            ))}
          </ul>
        ) : (
          <p className="text-[1.15rem] leading-tight">Every pot has room this month.</p>
        )}
      </StickyNoteContent>
    </StickyNote>
  )
}

import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { BarChart, ChartContainer, ChartLegend, ChartTooltip, ChartTooltipContent, DonutChart, type ChartConfig } from "@/components/ui/chart"
import { cn } from "@/lib/utils"
import { CATEGORIES, cashFlow, money, spentBy, type Transaction } from "@/components/blocks/dashboard-finance/components/dashboard-finance-data"

const flowConfig = {
  income: { label: "Money in", color: "var(--chart-3)" },
  spending: { label: "Money out", color: "var(--chart-1)" },
} satisfies ChartConfig

const dollars = (n: number) => money(Math.round(n) * 100).replace(/\.00$/, "")

export function CashFlow({ list, className }: { list: readonly Transaction[]; className?: string }) {
  const data = cashFlow(list)
  return (
    <Card className={cn("min-w-0", className)} seed="finance-flow">
      <CardHeader>
        <CardTitle role="heading" aria-level={2}>
          In and out
        </CardTitle>
        <CardDescription>Money in against money out, April to September</CardDescription>
      </CardHeader>
      <CardContent>
        <ChartContainer config={flowConfig} className="aspect-auto h-64 w-full">
          <BarChart
            data={data}
            xKey="month"
            label="Money in and money out per month, April to September"
            yFormatter={(v) => dollars(v)}
            valueFormatter={(v) => dollars(v)}
            annotations={[{ at: "min", series: "income", text: "a slow month" }]}
          />
          <ChartTooltip content={<ChartTooltipContent indicator="dot" />} />
          <ChartLegend />
        </ChartContainer>
      </CardContent>
    </Card>
  )
}

const slug = (c: string) => c.toLowerCase().replace(/[^a-z]+/g, "-")

export function Spending({ list, month, monthName, className }: { list: readonly Transaction[]; month: string; monthName: string; className?: string }) {
  const spent = spentBy(list, month)
  const data = CATEGORIES.filter((c) => spent[c]).map((c) => ({ category: slug(c), cents: spent[c] }))
  const config = Object.fromEntries(CATEGORIES.filter((c) => spent[c]).map((c) => [slug(c), { label: c }])) satisfies ChartConfig
  const total = data.reduce((a, d) => a + d.cents, 0)
  return (
    <Card className={cn("min-w-0", className)} seed="finance-spending">
      <CardHeader>
        <CardTitle role="heading" aria-level={2}>
          Where it went
        </CardTitle>
        <CardDescription>Money out in {monthName}, by category</CardDescription>
      </CardHeader>
      <CardContent>
        <ChartContainer config={config} className="aspect-auto h-64 w-full">
          <DonutChart
            data={data}
            nameKey="category"
            valueKey="cents"
            label={`Money out in ${monthName}, by category`}
            showLabels={false}
            valueFormatter={(v) => money(v)}
            centerLabel={{ value: dollars(total / 100), label: "spent" }}
          />
          <ChartTooltip />
          <ChartLegend />
        </ChartContainer>
      </CardContent>
    </Card>
  )
}
